base_friction = 0.92
base_acceleration = 0.15
limit_right = 150
limit_left = -170

self.speed = 0;
self.current_friction = base_friction - 0.02 * Stage.collected_boxes
self.current_acceleration = base_acceleration * (1 - Stage.collected_boxes * 0.2)

self.show()
self.set_size(0.22)
self.go_to_xy(0, -110)

while True:
    if pytch.key_pressed("a"):

        # if forklift is not hitting its left limit
        if self.x_position > limit_left:

            # if forklift is not moving to the left at full speed
            if (self.speed > -3):

                # if forklift is moving to the right
                if (self.speed > 0):
                    # apply friction
                    self.speed *= self.current_friction

                # accelerate to the left
                self.speed -= self.current_acceleration

            elif (self.speed < -3):
                self.speed = -3

    elif pytch.key_pressed("d"):

        # if forklift is not hitting its right limit
        if self.x_position < limit_right:

            # if forklift is not moving to the right at full speed
            if (self.speed < 3):

                # if forklift is moving to the left 
                if (self.speed < 0):
                    # apply friction 
                    self.speed *= self.current_friction

                # accelerate to the right
                self.speed += self.current_acceleration

            elif (self.speed > 3):
                self.speed = 3
        else:
            self.speed = 0
    else:
        if self.x_position < limit_left or self.x_position > limit_right:
            self.speed = 0

        # apply friction
        self.speed *= self.current_friction

    self.change_x(self.speed)

    # get points for delivering carried boxes 
    if self.touching(DropPoint) and Stage.collected_boxes > 0:
        pytch.broadcast("award-points")
        self.switch_costume(0)
